(10,1,'2026-07-28 02:00:56','2026-07-27 20:00:56','<h1>Contact.</h1>							<ul>\n							<li>\n											<a href=\"https://solacewp.com/webcrafters/\">\n											Home\n											</a>\n									</li>\n								<li>\n										/\n									</li>\n								<li>\n										Contact\n									</li>\n						</ul>\n																	<img width=\"1844\" height=\"1037\" src=\"http://localhost:10073/wp-content/uploads/2026/07/desk-with-multiple-computer-monitors-displaying-ne-PMBWC2A.jpg\" alt=\"\" />																<h3>Have a question?</h3>					<h2>Send us a message.</h2>				\n		<form method=\"post\" data-post_id=\"\" data-el_id=\"604c90f1\" enctype=\"multipart/form-data\">\n									<label>Name</label>\n						<input\n										name=\"name\"\n													get_label=\"Name\"\n								type=\"text\"\n				class=\"solaceform-input  solaceform-style-field\"\n				placeholder=\"\"\n										accept=&quot;&quot;			>\n									<label>Email</label>\n						<input\n										name=\"email\"\n													get_label=\"Email\"\n								type=\"email\"\n				class=\"solaceform-input  solaceform-style-field\"\n				placeholder=\"\"\n										accept=&quot;&quot;			>\n									<label>Message</label>\n						<textarea\n				name=\"msg\"\n				class=\"solaceform-input  solaceform-style-field\"\n				rows=\"4\"\n				placeholder=\"\"\n							get_label=\"Message\"\n										></textarea>\n				<button type=\"submit\" id=\"\">\n							Send						\n				</button>\n		</form>\n		<style>\n			.solaceform-container {\n				display: flex;\n				flex-wrap: wrap;\n				width: 100%;\n			}\n			.solaceform-field-column,\n			.solaceform-button-column,\n			.solaceform-input,\n			.submit-button {\n				box-sizing: border-box;\n			}\n			.solaceform-input,\n			.submit-button {\n				width: 100%;\n				white-space: nowrap;\n			}\n		</style>\n							<h5>New Jersey</h5>							<ul>\n							<li>\n											<a href=\"#\">\n											1428 Callison Lane Building 201 Virginia, VA 22902\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											hello@yourwebsite.com\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											+1.555.897.1234\n											</a>\n									</li>\n						</ul>\n							<h5>Los Angeles</h5>							<ul>\n							<li>\n											<a href=\"#\">\n											Via Venezia 118 San Giacomo D Cosenza 87040\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											hello@yourwebsite.com\n											</a>\n									</li>\n								<li>\n											<a href=\"#\">\n											1.878.459.222\n											</a>\n									</li>\n						</ul>\n							<h5>We are trusted by more than 5973 world-class companies</h5>															<img width=\"2284\" height=\"973\" src=\"http://localhost:10073/wp-content/uploads/2026/07/new-logocarousel-2.png\" alt=\"\" />																										<img width=\"2284\" height=\"973\" src=\"http://localhost:10073/wp-content/uploads/2026/07/new-logocarousel-6.png\" alt=\"\" />																										<img width=\"2284\" height=\"973\" src=\"http://localhost:10073/wp-content/uploads/2026/07/new-logocarousel-3.png\" alt=\"\" />																										<img width=\"2284\" height=\"973\" src=\"http://localhost:10073/wp-content/uploads/2026/07/new-logocarousel-1.png\" alt=\"\" />																										<img width=\"2284\" height=\"973\" src=\"http://localhost:10073/wp-content/uploads/2026/07/new-logocarousel-5.png\" alt=\"\" />																										<img width=\"2284\" height=\"973\" src=\"http://localhost:10073/wp-content/uploads/2026/07/new-logocarousel.png\" alt=\"\" />																Our Locations					<h2>Find some of our locations.</h2>							\n									<h5>\n							New York, NY						\n					</h5>\n									<p>\n						123 Main Street, Suite 101\n<br>\n(206) 123-4567					</p>\n												<a href=\"#\">\n									Get directions\n					</a>\n									<h5>\n							Los Angeles, CA						\n					</h5>\n									<p>\n						78 Sunset Street, Suite 300\n<br>\n(713) 555-1234					</p>\n												<a href=\"